import ../verify-creation.bend as Consumer
import ../verify-upload-mutations.bend as Files
import ../upload-boundary/scan.bend as S

def forest_moved(pair:Scene.Application() & List<&2,HW.Row>) -> IO(Unit):
  (app,+rows) = pair
  do IO<Unit>:
    root:W.Handle<D.Schema> <- Check.entity(Check.at(rows,0n))
    app:Scene.Application() <- Check.accepted(Scene.set_transform(app,root,Scenes.pose(0.5,0.25,0.0,C.Quat{0.0,0.0,0.6,0.8},C.Vec3{2.0,0.5,1.0})),True{})
    checked:Scene.Application() & List<&2,HW.Row> <- Check.observe(app)
    return Unit{}

def forest(mode:U32,count:Nat) -> IO(Unit):
  do IO<Unit>:
    compiled:Create.Compiled <- Consumer.compiled(Create.compile(Create.Scene{Scenes.forest(count,mode,0)}))
    pair:Scene.Application() & List<&2,HW.Row> <- Drive.start(compiled)
    forest_moved(pair)

def compile_rejected(result:Result<&2,&2,Create.Error,Create.Compiled>) -> Bool:
  match result:
    case Fail{Create.BadHierarchy{_}}:True{}
    case _:False{}

def rejects() -> IO(Unit):
  do IO<Unit>:
    S.require(compile_rejected(Create.compile(Create.Scene{[Create.Parented{Scenes.mesh(),F.white(),C.Transform.identity(),0}]})),"Creation self-parent accepted")
    S.require(compile_rejected(Create.compile(Create.Scene{[Create.Parented{Scenes.mesh(),F.white(),C.Transform.identity(),9}]})),"Creation missing parent accepted")
    S.require(compile_rejected(Create.compile(Create.Scene{[Create.Parented{Scenes.mesh(),F.white(),C.Transform.identity(),1},Create.Parented{Scenes.mesh(),F.white(),C.Transform.identity(),0}]})),"Creation cycle accepted")
    return Unit{}

def placement(parent:String) -> String:
  "{\"model\":\"sign\",\"parent\":" ++ parent ++ ",\"transform\":{\"position\":[0,0,0],\"rotation\":[0,0,0,1],\"scale\":[1,1,1]}}"

def document(a:String,b:String,c:String) -> String:
  "{\"version\":1,\"manifest\":\"manifest.json\",\"instances\":[" ++ placement(a) ++ "," ++ placement(b) ++ "," ++ placement(c) ++ "]}"

def parents(values:List<&2,H.Local>) -> String:
  match values:
    case []:""
    case H.Local{_,p,_,_} <> rest:Check.parent_words(p) ++ "," ++ parents(rest)

def loaded(result:Result<&2,&2,Asset.Error,Create.Scene>,valid:Bool,expected:String) -> IO(Unit):
  match result:
    case Fail{_}:S.require(Bool.not(valid),"Valid hierarchy JSON rejected")
    case Done{+scene}:
      Create.Scene{+items} = scene
      do IO<Unit>:
        S.require(valid,"Invalid hierarchy JSON accepted")
        S.require(String.eq(parents(Create.locals(items)),expected),"Hierarchy JSON placement parents or model anchors differ")
        compiled:Create.Compiled <- Consumer.compiled(Create.compile(Create.Scene{items}))
        pair:Scene.Application() & List<&2,HW.Row> <- Drive.start(compiled)
        return Unit{}

def json_case(+dir:String,+a:String,b:String,c:String,valid:Bool) -> IO(Unit):
  do IO<Unit>:
    Files.save(dir ++ "/scene.json",document(a,b,c))
    result:Result<&2,&2,Asset.Error,Create.Scene> <- Json.load(dir ++ "/scene.json")
    loaded(result,valid,Bool.pick(String,String.eq(a,"2"),"6,0,0,0,3,3,root,6,6,","root,0,0,0,3,3,3,6,6,"))

def json() -> IO(Unit):
  do IO<Unit>:
    _:String <- S.run("mkdir",["-p","build/verification"])
    path:String <- S.run("mktemp",["-d","build/verification/hierarchy-json-XXXXXXXX"])
    +dir:String = String.trim(path)
    _:String <- S.run("cp",["docs/verification/2026-11-04-json-scene/corpus/manifest.json","docs/verification/2026-11-04-json-scene/corpus/sign.obj","docs/verification/2026-11-04-json-scene/corpus/sign.mtl","docs/verification/2026-11-04-json-scene/corpus/image.png",dir])
    json_case(dir,"2","0","null",True{})
    json_case(dir,"0","null","null",False{})
    json_case(dir,"1","2","0",False{})
    json_case(dir,"3","null","null",False{})
    json_case(dir,"1.0","null","null",False{})
    json_case(dir,"-1","null","null",False{})
    json_case(dir,"null","0","1",True{})
    IO.print("Hierarchy JSON forward references, model-part anchors and invalid graph rejection passed")

def finish(pair:Scene.Application() & List<&2,HW.Row>) -> IO(Unit):
  (app,rows) = pair
  IO.print("Hierarchy ECS complete-state verification passed")

def main() -> IO(Unit):
  do IO<Unit>:
    rejects()
    forest(0,32n)
    forest(1,128n)
    forest(2,63n)
    IO.print("Flat, deep and branching real ECS point/bounds oracle passed")
    pair:Scene.Application() & List<&2,HW.Row> <- Drive.boot()
    pair:Scene.Application() & List<&2,HW.Row> <- Drive.series(Drive.codes(),pair)
    finish(pair)
    json()
import Base
import ./check.bend as Check
import ./scenes.bend as Scenes
import ../../src/scene.bend as Scene
import ../../src/creation.bend as Create
import ../../src/scene-schema.bend as D
import ../../src/scene-hierarchy.bend as HW
import ../../src/components.bend as C
import ../../src/hierarchy.bend as H
import ../../src/scene-matrix.bend as M
import ../../deps/bendvy/src/ecs/world.bend as W
import ../verify-creation.bend as Consumer
import ../upload-boundary/scan.bend as S

def foreign(entity:W.Handle<D.Schema>) -> W.Handle<D.Schema>:
  W.Handle{namespace,key} = entity
  W.Handle{U32.inc(namespace),key}

def action(code:U32,app:Scene.Application(),+root:W.Handle<D.Schema>,+child:W.Handle<D.Schema>,+branch:W.Handle<D.Schema>,+other:W.Handle<D.Schema>,deep:W.Handle<D.Schema>) -> IO(Scene.Application()):
  match code:
    case 0:
      do IO<Scene.Application()>:
        app:Scene.Application() <- Check.accepted(Scene.set_parent(app,child,Some{root}),True{})
        app:Scene.Application() <- Check.accepted(Scene.set_transform(app,root,Scenes.root()),True{})
        Check.accepted(Scene.set_transform(app,child,Scenes.child()),True{})
    case 1:Check.accepted(Scene.set_transform(app,root,Scenes.pose(0.1,0.1,0.5,Scenes.rotation(),C.Vec3{0.8,0.6,0.5})),True{})
    case 2:Check.accepted(Scene.set_transform(app,root,Scenes.pose(F32.neg(0.3),0.0,0.5,C.Quat{0.0,0.0,0.6,0.8},C.Vec3{0.8,0.6,0.5})),True{})
    case 3:Check.accepted(Scene.set_transform(app,root,Scenes.pose(F32.neg(0.3),0.0,0.5,Scenes.rotation(),C.Vec3{1.2,0.4,0.8})),True{})
    case 4:Check.accepted(Scene.set_parent(app,child,Some{other}),True{})
    case 5:Check.accepted(Scene.set_parent(app,child,None{}),True{})
    case 6:Check.accepted(Scene.set_parent(app,child,Some{child}),False{})
    case 7:Check.accepted(Scene.set_parent(app,root,Some{deep}),False{})
    case 8:Check.accepted(Scene.set_parent(app,child,Some{foreign(root)}),False{})
    case 9:Check.accepted(Scene.set_transform(app,root,Scenes.pose(0.0,0.0,0.5,Scenes.rotation(),C.Vec3{0.0,1.0,1.0})),False{})
    case 10:Check.accepted(Scene.set_transform(app,root,Scenes.pose(M.float_word(2139095040),0.0,0.5,Scenes.rotation(),Scenes.unit())),False{})
    case 11:Check.accepted(Scene.set_transform(app,foreign(root),Scenes.root()),False{})
    case 12:Check.accepted(Scene.set_transform(app,branch,Scenes.pose(0.0,0.8,0.0,C.Quat{0.6,0.0,0.0,0.8},C.Vec3{0.3,0.3,0.3})),True{})
    case 13:Scene.tick(app)
    case _:IO.die(Scene.Application(),1,"Unknown hierarchy replay command")

def independent(before:List<&2,HW.Row>,after:List<&2,HW.Row>) -> Bool:
  match before after:
    case [_,_,_,a,_], [_,_,_,b,_]:String.eq(Check.row_words(a),Check.row_words(b))
    case _ _:False{}

def verified(+code:U32,+before:List<&2,HW.Row>,pair:Scene.Application() & List<&2,HW.Row>) -> IO(Scene.Application() & List<&2,HW.Row>):
  (app,+rows) = pair
  do IO<Scene.Application() & List<&2,HW.Row>>:
    S.require(Bool.pick(Bool,U32.is_ge(code,6) && U32.is_le(code,11),String.eq(Check.state(before),Check.state(rows)),True{}),"Rejected hierarchy edit changed complete ECS state")
    S.require(U32.is_eq(code,13) || independent(before,rows),"Hierarchy edit changed independent branch")
    IO.print_err("hierarchy-step=" ++ U32.show(code) ++ " state=" ++ Check.state(rows))
    return (app,rows)

def step(+code:U32,pair:Scene.Application() & List<&2,HW.Row>) -> IO(Scene.Application() & List<&2,HW.Row>):
  (app,+before) = pair
  do IO<Scene.Application() & List<&2,HW.Row>>:
    root:W.Handle<D.Schema> <- Check.entity(Check.at(before,0n))
    child:W.Handle<D.Schema> <- Check.entity(Check.at(before,1n))
    branch:W.Handle<D.Schema> <- Check.entity(Check.at(before,2n))
    other:W.Handle<D.Schema> <- Check.entity(Check.at(before,3n))
    deep:W.Handle<D.Schema> <- Check.entity(Check.at(before,4n))
    app:Scene.Application() <- action(code,app,root,child,branch,other,deep)
    pair:Scene.Application() & List<&2,HW.Row> <- Check.observe(app)
    verified(code,before,pair)

def start(compiled:Create.Compiled) -> IO(Scene.Application() & List<&2,HW.Row>):
  Create.Compiled{seeds,_} = compiled
  do IO<Scene.Application() & List<&2,HW.Row>>:
    app:Scene.Application() <- Scene.create(seeds)
    app:Scene.Application() <- Scene.tick(app)
    Check.observe(app)

def boot() -> IO(Scene.Application() & List<&2,HW.Row>):
  do IO<Scene.Application() & List<&2,HW.Row>>:
    compiled:Create.Compiled <- Consumer.compiled(Create.compile(Scenes.showcase()))
    start(compiled)

def series(codes:List<&2,U32>,pair:Scene.Application() & List<&2,HW.Row>) -> IO(Scene.Application() & List<&2,HW.Row>):
  match codes:
    case []:IO.pure(Scene.Application() & List<&2,HW.Row>,pair)
    case code <> rest:
      do IO<Scene.Application() & List<&2,HW.Row>>:
        next:Scene.Application() & List<&2,HW.Row> <- step(code,pair)
        series(rest,next)

