    case True{} False{}:Fail{InvalidTransform{index}}
    case True{} True{}:next

def normal_transform(range:Maybe<Create.Range>,transform:C.Transform) -> Bool:
  match range:
    case Some{Create.Range{_,_,_,Some{_}}}:Light.transform_valid(transform)
    case _:True{}

def normal_global(range:Maybe<Create.Range>,global:H.GlobalTransform) -> Bool:
  match range:
    case Some{Create.Range{_,_,_,Some{_}}}:H.usable_normal(H.normal(global))
    case _:True{}

def preflight(+camera:M.Mat4,+ranges:List<&2,Create.Range>,items:List<&2,Draw.DrawItem>,+index:U32) -> Result<&2,&2,InputError,Unit>:
  match items:
    case []:Done{Unit{}}
    case Draw.DrawItem{+t,C.MeshRef{+other}} <> rest:
      preflight_item(known(Create.resolve(ranges,other)),Create.transform_valid(t) && normal_transform(Create.resolve(ranges,other),t) && Create.matrix_finite(M.multiply(camera,M.model(t))),other,index,preflight(camera,ranges,rest,U32.inc(index)))
    case Draw.GlobalItem{+t,C.MeshRef{+other}} <> rest:
      preflight_item(known(Create.resolve(ranges,other)),H.affine(t) && normal_global(Create.resolve(ranges,other),t) && Create.matrix_finite(M.multiply(camera,H.matrix(t))),other,index,preflight(camera,ranges,rest,U32.inc(index)))

def allocate(+instance:V.Instance,+physical:V.PhysicalDevice,+device:V.Device,requirements:V.MemoryRequirements,flags:U32) -> V.Action(V.DeviceMemory):
  V.MemoryRequirements{size,_,bits} = requirements
  do V.Action<V.DeviceMemory>:
    types : List<Core.MemoryType> <- V.Instance.get_physical_device_memory_properties(instance,physical)
    index : U32 <- choose(Core.find_memory_type(types,bits,flags),"No compatible memory")
    V.Device.allocate_memory(device,size,index)

def attachment(+instance:V.Instance,+physical:V.PhysicalDevice,+device:V.Device,+extent:V.Extent2D,+format:U32,+aspect:U32,+usage:U32) -> V.Action(Attachment):
  do V.Action<Attachment>:
    supported : V.ImageFormatProperties <- V.Instance.get_physical_device_image_format_properties(instance,physical,V.ImageFormatInfo{format,vk.VK_IMAGE_TYPE_2D(),vk.VK_IMAGE_TILING_OPTIMAL(),usage,0})
    +image : V.ImageHandle <- V.Device.create_image(device,V.ImageCreateInfo{format,extent,1,1,usage})
    req : V.MemoryRequirements <- V.Device.get_image_memory_requirements(device,image)
    +memory : V.DeviceMemory <- allocate(instance,physical,device,req,0)
    V.Device.bind_image_memory(device,image,memory,W.zero())
    view : V.ImageView <- V.Device.create_image_view(device,V.ImageViewCreateInfo{image,1,V.ImageSubresourceRange{aspect,0,1,0,1}})
    return Attachment{image,memory,view}

def aligned(+size:U32,alignment:W.U64) -> W.U64:
  W.U64{+lo,+hi} = alignment
  W.of_u32(U32.mul(U32.div(U32.add(size,U32.sub(lo,1)),lo),lo))
import Base
import ./components.bend as C
import ./content.bend as F
import ./scene-matrix.bend as M
import ./hierarchy.bend as H

type Light is Data:
  Directional{toward:C.Vec3,color:C.Vec3,ambient:F32,intensity:F32}

def default() -> Light:
  Directional{C.Vec3{0.4,0.7,1.0},C.Vec3{1.0,1.0,1.0},0.2,0.8}

def valid(light:Light) -> Bool:
  Directional{direction,color,ambient,intensity} = light
  F.normal_valid(direction) && F.tint_valid(color) && F.channel(ambient) && F.channel(intensity)

def scale_valid(scale:C.Vec3) -> Bool:
  C.Vec3{+x,+y,+z} = scale
  F32.is_ge(F32.abs(x),0.000001) && F32.is_ge(F32.abs(y),0.000001) && F32.is_ge(F32.abs(z),0.000001) && F32.is_le(F32.abs(x),1000000.0) && F32.is_le(F32.abs(y),1000000.0) && F32.is_le(F32.abs(z),1000000.0)

def transform_valid(transform:C.Transform) -> Bool:
  C.Transform{_,_,scale} = transform
  scale_valid(scale)

def normal_words(matrix:M.Mat4,light:Light) -> List<U32>:
  M.Mat4{M.Vec4{a,b,c,_},M.Vec4{d,e,f,_},M.Vec4{g,h,i,_},_} = matrix
  Directional{C.Vec3{dx,dy,dz},C.Vec3{r,g1,b1},ambient,+intensity} = light
  [F32.bits(a),F32.bits(b),F32.bits(c),F32.bits(dx),
   F32.bits(d),F32.bits(e),F32.bits(f),F32.bits(dy),
   F32.bits(g),F32.bits(h),F32.bits(i),F32.bits(dz),
   F32.bits(F32.mul(r,intensity)),F32.bits(F32.mul(g1,intensity)),F32.bits(F32.mul(b1,intensity)),F32.bits(ambient)]

def normal_payload(camera:M.Mat4,global:H.GlobalTransform,light:Light,normal:Maybe<&2,M.Mat4>) -> List<U32>:
  match normal:
    case None{}:[]
    case Some{matrix}:List.append(&1,U32,M.matrix_words(M.multiply(camera,H.matrix(global))),normal_words(matrix,light))

def global_payload(camera:M.Mat4,+global:H.GlobalTransform,light:Light) -> List<U32>:
  normal_payload(camera,global,light,H.normal(global))

def payload(camera:M.Mat4,transform:C.Transform,light:Light) -> List<U32>:
  global_payload(camera,H.compose(None{},transform),light)
